"""Embed every map in maps/ into mybot/maps_data.hpp as raw string literals.

Run after `unswbc maps` / `unswbc update` brings in new or changed maps:
    python tools/gen_maps.py [maps_dir] [out_header]
"""

import pathlib
import sys

root = pathlib.Path(__file__).resolve().parents[1]
maps_dir = pathlib.Path(sys.argv[1]) if len(sys.argv) > 1 else root / "maps"
out = pathlib.Path(sys.argv[2]) if len(sys.argv) > 2 else root / "mybot" / "maps_data.hpp"

paths = sorted(maps_dir.glob("*.map"))
names = ", ".join(f'"{p.stem}"' for p in paths)
parts = [
    "// Generated by tools/gen_maps.py -- do not edit by hand.\n",
    "#pragma once\n\n",
    "namespace maps_data {\n\n",
    "// File names without .map, in the same order as MAPS (profiles.hpp keys on these).\n",
    f"inline const char* const NAMES[] = {{{names}}};\n\n",
    "inline const char* const MAPS[] = {\n",
]
count = 0
for path in paths:
    lines = []
    for line in path.read_text().splitlines():
        line = line.strip()
        if line and not line.startswith("MAP_NAME") and not line.startswith("#"):
            lines.append(line)
    text = "\n".join(lines)
    assert ")MAP\"" not in text
    parts.append(f"    // {path.name}\n    R\"MAP({text}\n)MAP\",\n")
    count += 1
parts.append("};\n\n")
parts.append(f"inline constexpr int MAP_COUNT = {count};\n\n")
parts.append("} // namespace maps_data\n")
out.write_text("".join(parts))
print(f"wrote {count} maps to {out} ({out.stat().st_size // 1024} KB)")
